from functools import lru_cache

from transformers import pipeline

@lru_cache(maxsize=1)
def modeles():
    """Chargés une seule fois au démarrage de l'API IA."""
    return {
        "traduction": pipeline("translation", model="Helsinki-NLP/opus-mt-fr-en"),
        "sentiment": pipeline("sentiment-analysis",
                              model="nlptown/bert-base-multilingual-uncased-sentiment"),
    }

def analyser(message: str) -> dict:
    m = modeles()
    etoiles = int(m["sentiment"](message)[0]["label"].split()[0])   # « 4 stars » -> 4
    sentiment = "positif" if etoiles >= 4 else "négatif" if etoiles <= 2 else "neutre"
    return {"original": message,
            "anglais": m["traduction"](message)[0]["translation_text"],
            "sentiment": sentiment}
